mapper.update:
update agent
set agent_name = #{agentName},
    description = #{description},
    status = #{status},
    current_published_version_id = #{currentPublishedVersionId},
    updated_by = #{updatedBy},
    updated_at = #{updatedAt}
where org_id = #{orgId}
  and agent_code = #{agentCode}

mapper.select:
select count(1)
from agent
where org_id = #{orgId}

    and status = #{status}


    and (
        agent_code like concat('%', #{keyword}, '%')
        or agent_name like concat('%', #{keyword}, '%')
    )

select id, org_id, agent_code, agent_name, description, status, current_published_version_id, created_by, updated_by, created_at, updated_at from agent where org_id = #{orgId}
and status = #{status}
and ( agent_code like concat('%', #{keyword}, '%') or agent_name like concat('%', #{keyword}, '%') )
order by updated_at desc, id asc limit #{pageSize} offset #{offset}
